public class Counter {
    private int n;

    public void increment() {
        n++;
    }

    public void decrement() {
        if (n > 0) {
            n--;
        }
    }

    public int value() {
        return n;
    }
}

class Counter:
    def __init__(self) -> None:
        self._n = 0

    def increment(self) -> None:
        self._n += 1

    def decrement(self) -> None:
        if self._n > 0:
            self._n -= 1

    def value(self) -> int:
        return self._n
